// ============================================================
// Inner SPARC Realty Corporation — Agent Portal
// Auth.gs — Authentication & Authorization backend
//
// Implements every pa_* function Portal.html and PortalData.gs
// already call. Reads/writes the "Agent Access", "Credentials",
// "Login Tokens", and "Sessions" tabs, which live in the SAME
// spreadsheet as the commission data (TARGET_SHEET_ID, defined
// in Code.gs) — the two were merged into one spreadsheet so
// there's a single file to manage instead of two. Auth.gs and
// Code.gs share one Apps Script global scope, so it calls
// getTargetSpreadsheet() directly rather than keeping its own
// separate spreadsheet ID (which could otherwise drift out of
// sync with Code.gs's).
//
// SETUP:
//   1. Make sure the "Agent Access", "Credentials", "Login Tokens",
//      and "Sessions" tabs exist in the TARGET_SHEET_ID spreadsheet
//      (see CreateDedicatedDatabase.gs if you need to (re)create them —
//      point it at TARGET_SHEET_ID instead of creating a new file).
//   2. Deploy this project as a web app so login/reset links
//      resolve to the right URL.
//   3. Add real rows to the "Agent Access" tab (Email, Canonical Name,
//      Role, Active, [Status], Aliases) for every agent who should be able to log in.
//      If you are upgrading an existing sheet whose column C was "Aliases",
//      run pa_migrateAgentAccessCanonicalName() once (see below).
//
// THE "ACTIVE" TOGGLE: unchecking Active marks an agent as inactive/
// resigned. It does NOT block that person from logging in — they can
// still authenticate with their password like anyone else. What it
// restricts is scope once logged in: an inactive session
// is limited to a read-only, PDF-only view of their own commission
// record (Dashboard) plus their Profile (so they can still change their
// password); Sales History, sale drilldowns, the chatbot, and Admin are
// all off-limits. That gating lives in PortalData.gs
// (pa_requireActiveAgent_) and PortalChat.gs — this file only surfaces
// the flag (pa_getAccessRecord_'s `active`, pa_validateSession's
// `isActive`) rather than enforcing it itself.
// =============================================================

const SHEET_AGENT_ACCESS = "Agent Access";
const SHEET_CREDENTIALS = "Credentials";
const SHEET_LOGIN_TOKENS = "Login Tokens";
const SHEET_SESSIONS = "Sessions";

const TOKEN_TTL_MINUTES = 30;
const SESSION_TTL_HOURS = 24 * 7; // 7 days
const TOKEN_REQUEST_COOLDOWN_SECONDS = 60; // minimum gap between new links of the same type for the same email

// Inner SPARC logo, inlined as a data URI so branded emails render the
// logo with zero external requests (no broken-image icon if the mail
// client blocks remote images) and no extra file to host/maintain.
// Shared by every branded email template below.
const PA_EMAIL_LOGO_DATA_URI = "data:image/png;base64,";

// Team photo shown on branded emails, hosted externally (see the
// email-templates section below for where it's used).
const PA_EMAIL_TEAM_PHOTO_URL_ = "https://i.imgur.com/j4iFl10.png"; // ← replace with your real Imgur link

// ── Spreadsheet / sheet access ──────────────────────────────
/** Same spreadsheet as the commission data — see the file header above. */
function pa_authSpreadsheet_() {
  return getTargetSpreadsheet(); // defined in Code.gs
}

// ── Agent Access column layout ──────────────────────────────
//   A User ID | B Email | C Canonical Name | D Role | E Active | F Status | G Aliases
//
// Column F ("Status") belongs to the sheet owner — this code NEVER writes to
// it (it is not read either). Aliases sits in G, after Status, so nothing that
// already lives in A:F is overwritten or shifted.
//
// "Canonical Name" is the ONE official spelling of the person's name. It is
// the portal display name and the Agents-roster Full Name.
// "Aliases" holds every OTHER spelling that appears in the Sales Agent
// column, semicolon-separated (semicolon, not comma, because names like
// "FLORES, JULIE FE" contain commas).
// Aliases lives in G (not beside C) so Role/Active keep their original
// positions D/E — every fixed-index read, the Role dropdown and the Active
// checkbox validation stay valid without moving any existing data.
// Sales matching uses Canonical Name + Aliases together (see
// pa_buildAccessNames_), so nothing downstream needs to know about the split.
const AA_COL_ = { USER_ID: 0, EMAIL: 1, CANONICAL: 2, ROLE: 3, ACTIVE: 4, STATUS: 5, ALIASES: 6 }; // 0-based row-array indexes; add 1 for sheet columns
const AA_HEADERS_ = ["User ID", "Email", "Canonical Name", "Role", "Active", "Status", "Aliases"];
const AA_LEGACY_CANONICAL_HEADERS_ = ["aliases", "aliases (comma-separated)", "aliases (semicolon-separated)"];
let PA_AA_HEADERS_CHECKED_ = false; // once per execution

function pa_agentAccessSheet_() {
  const sh = pa_authSpreadsheet_().getSheetByName(SHEET_AGENT_ACCESS);
  pa_ensureAgentAccessHeaders_(sh);
  return sh;
}

/** Self-heal (same pattern as pa_goalSheet_): renames a legacy "Aliases"
 *  header in column C to "Canonical Name" and adds the new "Aliases" header
 *  in column G. Only touches a header cell that is blank or a known legacy
 *  name — never overwrites a header someone typed on purpose. Never moves
 *  or rewrites data rows. */
function pa_ensureAgentAccessHeaders_(sh) {
  if (PA_AA_HEADERS_CHECKED_ || !sh) return;
  PA_AA_HEADERS_CHECKED_ = true;
  try {
    const aliasCol = AA_COL_.ALIASES + 1;
    if (sh.getMaxColumns() < aliasCol) sh.insertColumnsAfter(sh.getMaxColumns(), aliasCol - sh.getMaxColumns());
    const hdr = sh.getRange(1, 1, 1, aliasCol).getValues()[0].map(h => String(h || '').trim());
    const c = hdr[AA_COL_.CANONICAL];
    if (c !== AA_HEADERS_[AA_COL_.CANONICAL] && (c === '' || AA_LEGACY_CANONICAL_HEADERS_.indexOf(c.toLowerCase()) !== -1)) {
      sh.getRange(1, AA_COL_.CANONICAL + 1).setValue(AA_HEADERS_[AA_COL_.CANONICAL]);
    }
    if (hdr[AA_COL_.ALIASES] === '') {
      sh.getRange(1, AA_COL_.ACTIVE + 1).copyTo(sh.getRange(1, aliasCol), SpreadsheetApp.CopyPasteType.PASTE_FORMAT, false);
      sh.getRange(1, aliasCol).setValue(AA_HEADERS_[AA_COL_.ALIASES]);
    }
  } catch (e) {
    Logger.log('pa_ensureAgentAccessHeaders_ failed: ' + e.toString());
  }
}

function pa_credentialsSheet_() {
  return pa_authSpreadsheet_().getSheetByName(SHEET_CREDENTIALS);
}

function pa_loginTokensSheet_() {
  return pa_authSpreadsheet_().getSheetByName(SHEET_LOGIN_TOKENS);
}

function pa_sessionsSheet_() {
  return pa_authSpreadsheet_().getSheetByName(SHEET_SESSIONS);
}

/** Returns all data rows (excluding header) for a sheet as raw values. */
function pa_sheetRows_(sh) {
  if (!sh || sh.getLastRow() < 2) return [];
  return sh.getRange(2, 1, sh.getLastRow() - 1, sh.getLastColumn()).getValues();
}

/** 1-indexed sheet row number for the first row whose given column matches value (case-insensitive), or -1. */
function pa_findRow_(sh, colIndex1Based, value) {
  const rows = pa_sheetRows_(sh);
  const needle = String(value || '').trim().toUpperCase();
  for (let i = 0; i < rows.length; i++) {
    if (String(rows[i][colIndex1Based - 1] || '').trim().toUpperCase() === needle) {
      return i + 2; // +1 for header row, +1 for 0-index -> 1-index
    }
  }
  return -1;
}

/**
 * Returns the 1-indexed row number of the last row that actually has data in
 * `keyCol1Based` — unlike sh.getLastRow(), this ignores trailing rows that
 * are blank except for checkbox-formatted columns. Applying Sheets'
 * "Insert checkboxes" to a wide range (e.g. Agent Access!E2:E500, or the
 * "Active"/"Password Set"/"Used" columns on the other auth tabs) writes a
 * literal FALSE into every one of those cells even though the row has no
 * other data — which makes getLastRow() report the bottom of that
 * pre-formatted range instead of the bottom of the real data. Every
 * appendRow()/insertRowAfter(getLastRow()) call in this file was landing
 * new rows hundreds of rows below the last real user, invisible unless you
 * scrolled all the way down — this is what pa_appendRowAfterData_() below
 * fixes. Returns 1 (the header row) if there's no data yet.
 */
function pa_lastRowWithData_(sh, keyCol1Based) {
  const lastRow = sh.getLastRow();
  if (lastRow < 2) return 1;
  const values = sh.getRange(2, keyCol1Based, lastRow - 1, 1).getValues();
  for (let i = values.length - 1; i >= 0; i--) {
    if (String(values[i][0] || '').trim() !== '') return i + 2;
  }
  return 1;
}

/** Writes `rowValues` into the row directly below the last row that has real
 *  data in `keyCol1Based` (see pa_lastRowWithData_ above) — reusing an
 *  existing blank-but-formatted row if one is sitting right there, and only
 *  extending the sheet if we've genuinely run out of rows. This replaces
 *  plain appendRow()/insertRowAfter(getLastRow()) everywhere in this file. */
function pa_appendRowAfterData_(sh, keyCol1Based, rowValues) {
  const insertAt = pa_lastRowWithData_(sh, keyCol1Based) + 1;
  if (insertAt > sh.getMaxRows()) {
    sh.insertRowsAfter(sh.getMaxRows(), insertAt - sh.getMaxRows());
  }
  sh.getRange(insertAt, 1, 1, rowValues.length).setValues([rowValues]);
  return insertAt;
}

function pa_normEmail_(s) {
  return String(s || '').trim().toLowerCase();
}

/** Splits a stored Agent Access "Aliases" cell into individual alias
 *  strings. Aliases are semicolon-separated — NOT comma-separated — because
 *  agent names routinely contain a literal comma themselves (this company's
 *  data regularly uses "Last, First" formatting, e.g. "FLORES, JULIE FE" —
 *  see Sales Agent / Buyer's Name columns throughout the Sales sheets).
 *  Splitting on comma silently broke any such name into two-plus bogus
 *  fragments (e.g. "FLORES, JULIE FE" -> "FLORES" + "JULIE FE"), neither of
 *  which matches the literal "FLORES, JULIE FE" text actually sitting in
 *  the Sales Agent column — so that agent's sales never matched any alias
 *  and silently vanished from her portal view, the same symptom as (but a
 *  separate root cause from) the multi-sheet-per-year bug in
 *  PortalData.gs's pa_getYearSalesSheets_().
 *  NOTE: any existing Agent Access row that used a comma to separate
 *  MULTIPLE aliases (e.g. "John Palonson, JP Palonson") needs to be
 *  updated in the Admin panel to use a semicolon instead
 *  ("John Palonson; JP Palonson") now that comma is a valid, unsplit
 *  character within a single alias. */
function pa_parseAliasesCsv_(aliasesCsv) {
  return String(aliasesCsv || '').split(';').map(a => a.trim()).filter(Boolean);
}

/** Case/whitespace-insensitive key used only to de-duplicate names. */
function pa_nameKey_(s) {
  return String(s || '').replace(/\s+/g, ' ').trim().toLowerCase();
}

/** Trims and collapses whitespace. Returns null if the value contains ';' —
 *  a canonical name is exactly ONE name; other spellings go in Aliases. */
function pa_cleanCanonicalName_(s) {
  const v = String(s || '').replace(/\s+/g, ' ').trim();
  return v.indexOf(';') === -1 ? v : null;
}

/** Combines the Canonical Name cell (col C) and Aliases cell (col G) into:
 *    canonicalName — the one official name ('' if blank)
 *    aliases       — canonical FIRST, then every alias, de-duplicated. This is
 *                    what all sales matching uses, and aliases[0] is the
 *                    display name, exactly as before the split.
 *    extraAliases  — aliases minus the canonical name (what the Aliases
 *                    column should hold)
 *  Tolerates a not-yet-migrated row where column C still holds
 *  "Name A; Name B": the first entry is treated as canonical and the rest
 *  are folded into the aliases, so nothing stops working before the
 *  migration has been run. */
function pa_buildAccessNames_(canonicalCell, aliasesCell) {
  const fromC = pa_parseAliasesCsv_(canonicalCell);
  const canonicalName = fromC[0] || '';
  const seen = {};
  const all = [];
  fromC.concat(pa_parseAliasesCsv_(aliasesCell)).forEach(n => {
    const k = pa_nameKey_(n);
    if (k && !seen[k]) { seen[k] = true; all.push(n); }
  });
  return { canonicalName: canonicalName, aliases: all, extraAliases: canonicalName ? all.slice(1) : all };
}

/** ONE-TIME migration for a sheet whose column C used to be "Aliases"
 *  ("Name A; Name B; Name C"). Run manually from the Apps Script editor.
 *  Renames the column C header to "Canonical Name", adds the "Aliases"
 *  header in G, and for every row with more than one name in C keeps the
 *  first name in C and moves the rest to G. Column F (Status) is never touched. Rows that already hold a single
 *  name are left untouched. Safe to run more than once. */
function pa_migrateAgentAccessCanonicalName() {
  const sh = pa_authSpreadsheet_().getSheetByName(SHEET_AGENT_ACCESS);
  if (!sh) { Logger.log('No "' + SHEET_AGENT_ACCESS + '" tab found.'); return; }
  PA_AA_HEADERS_CHECKED_ = false;
  pa_ensureAgentAccessHeaders_(sh);

  const last = sh.getLastRow();
  if (last < 2) { Logger.log('Headers updated. No data rows to migrate.'); return; }
  const cRange = sh.getRange(2, AA_COL_.CANONICAL + 1, last - 1, 1);
  const fRange = sh.getRange(2, AA_COL_.ALIASES + 1, last - 1, 1); // Aliases (col G)
  const cVals = cRange.getValues();
  const fVals = fRange.getValues();
  let moved = 0;
  for (let i = 0; i < cVals.length; i++) {
    if (pa_parseAliasesCsv_(cVals[i][0]).length <= 1) continue; // already a single name
    const names = pa_buildAccessNames_(cVals[i][0], fVals[i][0]);
    cVals[i][0] = names.canonicalName;
    fVals[i][0] = names.extraAliases.join('; ');
    moved++;
  }
  if (moved) { cRange.setValues(cVals); fRange.setValues(fVals); }
  Logger.log('pa_migrateAgentAccessCanonicalName: headers updated; ' + moved + ' row(s) split into Canonical Name + Aliases.');
}

// ── Authorization: Agent Access ─────────────────────────────
/** Returns {userId, active, canonicalName, aliases:[...], extraAliases:[...], role}
 *  for an email, or null if not found. `aliases` = canonical name first, then
 *  every alias (see pa_buildAccessNames_) — this is what sales matching reads. */
function pa_getAccessRecord_(email) {
  const sh = pa_agentAccessSheet_();
  const rows = pa_sheetRows_(sh);
  const target = pa_normEmail_(email);
  for (let i = 0; i < rows.length; i++) {
    if (pa_normEmail_(rows[i][AA_COL_.EMAIL]) === target) {
      const names = pa_buildAccessNames_(rows[i][AA_COL_.CANONICAL], rows[i][AA_COL_.ALIASES]);
      const activeCell = rows[i][AA_COL_.ACTIVE];
      return {
        userId: rows[i][AA_COL_.USER_ID] || '',
        active: activeCell === true || String(activeCell).toUpperCase() === 'TRUE',
        canonicalName: names.canonicalName,
        aliases: names.aliases,
        extraAliases: names.extraAliases,
        role: rows[i][AA_COL_.ROLE] || ''
      };
    }
  }
  return null;
}

/** Generates the next sequential User ID (USR-001, USR-002, ...) by scanning existing Agent Access rows. */
function pa_generateUserId_() {
  const rows = pa_sheetRows_(pa_agentAccessSheet_());
  let max = 0;
  rows.forEach(r => {
    const m = String(r[0] || '').match(/USR-(\d+)/);
    if (m) max = Math.max(max, parseInt(m[1], 10));
  });
  return 'USR-' + String(max + 1).padStart(3, '0');
}

/**
 * Admin helper: adds a new authorized user with an auto-generated User ID.
 * Run manually from the Apps Script editor (Select function > pa_addAgentAccess_ > adjust args > Run),
 * or call it from an admin-only UI later.
 *
 * Does three things, each skipped if it would duplicate existing data:
 *   1. Appends a row to "Agent Access" — appendRow() always writes to the
 *      first empty row below the current last row, so the new user always
 *      lands below the latest existing user, never overwriting anyone.
 *   2. Appends a matching row to "Credentials" (Password Set = false, no
 *      hash yet) so pa_getProfile() in PortalData.gs has a row to read
 *      immediately instead of erroring on a missing record. Skipped if a
 *      Credentials row for this email already exists.
 *   3. If role is "Agent" (case-insensitive), also adds them to the
 *      "Agents" roster tab via addAgent() (Code.gs) — the tab the admin
 *      CMS reads from — using the Canonical Name as their Full Name. Skipped
 *      for non-Agent roles (Supervisor/Manager/Admin aren't sales agents
 *      and shouldn't appear in the agent roster), and skipped if an Agents
 *      row with this email already exists.
 */
// canonicalName = the one official name; aliasesCsv (optional) = other spellings, semicolon-separated.
function pa_addAgentAccess_(email, canonicalName, role, aliasesCsv) {
  email = pa_normEmail_(email);
  const results = { userId: null, agentAccess: 'skipped', credentials: 'skipped', agentsRoster: 'skipped' };

  // 1. Agent Access
  const accessSh = pa_agentAccessSheet_();
  const existingAccess = pa_findRow_(accessSh, 2, email); // column B = Email
  if (existingAccess !== -1) {
    Logger.log('pa_addAgentAccess_: ' + email + ' already has an Agent Access row (row ' + existingAccess + ') — not duplicating.');
    results.userId = accessSh.getRange(existingAccess, 1).getValue();
  } else {
    const userId = pa_generateUserId_();
    pa_insertAgentAccessRowBelowLast_(userId, email, canonicalName, role, true, aliasesCsv);
    Logger.log('pa_addAgentAccess_: added ' + userId + ' for ' + email + ' to Agent Access (below the last existing row).');
    results.userId = userId;
    results.agentAccess = 'added';
  }

  // 2 & 3. Credentials + Agents roster — shared with the onEdit path
  // (pa_onAgentAccessEdit_ below) so a manual row typed straight into
  // the sheet gets the exact same treatment as a programmatic add.
  const provisioned = pa_ensureUserRecords_(email, canonicalName, role);
  results.credentials = provisioned.credentials;
  results.agentsRoster = provisioned.agentsRoster;

  Logger.log('pa_addAgentAccess_ summary for ' + email + ': ' + JSON.stringify(results));
  return results;
}

/**
 * Ensures Credentials (always) and Agents-roster (only if role is
 * "Agent") rows exist for `email` — each skipped if it would duplicate
 * an existing row. This is exactly steps 2 & 3 of pa_addAgentAccess_
 * above, pulled out so pa_onAgentAccessEdit_ (manual row added via the
 * Sheets UI) can call it too, without needing to touch Agent Access
 * itself (that row already exists — the admin just typed it in).
 * Returns { credentials: 'added'|'skipped', agentsRoster: 'added'|'skipped'|'failed' }.
 */
function pa_ensureUserRecords_(email, canonicalName, role) {
  email = pa_normEmail_(email);
  const result = { credentials: 'skipped', agentsRoster: 'skipped' };
  if (!email) return result;

  // Credentials — placeholder row so pa_getProfile() has something to
  // read before the user ever sets a password.
  try {
    const credSh = pa_credentialsSheet_();
    if (pa_findCredentialRow_(email) !== -1) {
      Logger.log('pa_ensureUserRecords_: ' + email + ' already has a Credentials row — not duplicating.');
    } else {
      pa_appendRowAfterData_(credSh, 1, [email, '', false, '', new Date()]); // Credentials: Email col A
      Logger.log('pa_ensureUserRecords_: added placeholder Credentials row for ' + email + '.');
      result.credentials = 'added';
    }
  } catch (e) {
    Logger.log('pa_ensureUserRecords_: could not add Credentials row for ' + email + ' — ' + e.toString());
  }

  // Agents roster — only for the "Agent" role, since Supervisor/Manager/
  // Admin accounts aren't sales agents and don't belong on that roster.
  if (String(role || '').trim().toLowerCase() === 'agent') {
    try {
      const existing = getAgents().find(a => pa_normEmail_(a['Email']) === email); // getAgents() defined in Code.gs
      if (existing) {
        Logger.log('pa_ensureUserRecords_: ' + email + ' already has an Agents roster row — not duplicating.');
      } else {
        const fullName = pa_parseAliasesCsv_(canonicalName)[0] || email;
        const added = addAgent({ fullName: fullName, email: email }); // defined in Code.gs
        Logger.log(added.success
          ? 'pa_ensureUserRecords_: added ' + email + ' to Agents roster as "' + fullName + '" (' + added.agentId + ').'
          : 'pa_ensureUserRecords_: addAgent() failed for ' + email + ' — ' + added.error);
        result.agentsRoster = added.success ? 'added' : 'failed';
      }
    } catch (e) {
      Logger.log('pa_ensureUserRecords_: could not add Agents roster row for ' + email + ' — ' + e.toString());
    }
  } else {
    Logger.log('pa_ensureUserRecords_: role "' + role + '" is not "Agent" — skipping Agents roster.');
  }

  return result;
}

/**
 * Ensures an Agent Access row (role "Agent") + Credentials row exist for
 * `email` — called from addAgent() in Code.gs so adding someone via the
 * Agents admin panel also grants them portal login access. This is the
 * Agents -> Agent Access direction; pa_ensureUserRecords_() above is the
 * reverse (Agent Access -> Agents). Never overwrites an existing Agent
 * Access row's role/aliases (e.g. if they're already a Supervisor, being
 * added to the Agents roster shouldn't silently demote them) — it's
 * skipped, not updated, if a row for this email already exists. Inserted
 * directly below the last existing row, same as every other add path.
 */
function pa_ensureAgentAccessForAgent_(email, fullName) {
  email = pa_normEmail_(email);
  if (!email) return { agentAccess: 'skipped', credentials: 'skipped' };

  const accessSh = pa_agentAccessSheet_();
  const existing = pa_findRow_(accessSh, 2, email);
  if (existing !== -1) {
    Logger.log('pa_ensureAgentAccessForAgent_: ' + email + ' already has an Agent Access row — not duplicating (role/aliases left as-is).');
    const provisioned = pa_ensureUserRecords_(email, '', accessSh.getRange(existing, AA_COL_.ROLE + 1).getValue());
    return { agentAccess: 'skipped', credentials: provisioned.credentials };
  }

  const userId = pa_generateUserId_();
  pa_insertAgentAccessRowBelowLast_(userId, email, fullName || '', 'Agent', true, '');
  Logger.log('pa_ensureAgentAccessForAgent_: added ' + userId + ' for ' + email + ' to Agent Access (role Agent).');

  // Credentials only, in effect — the Agents roster row already exists
  // (addAgent() just created it), so pa_ensureUserRecords_'s Agents-roster
  // step will simply find it and skip, which is fine (idempotent).
  const provisioned = pa_ensureUserRecords_(email, fullName || '', 'Agent');
  return { agentAccess: 'added', credentials: provisioned.credentials };
}

/**
 * Makes a manual addition — an admin typing a new row straight into the
 * "Agent Access" tab in the Sheets UI — get the same Credentials/Agents
 * provisioning that pa_addAgentAccess_() gives a programmatic add.
 * Called from onEdit(e) in Code.gs; never call this directly.
 *
 * Handles multi-row edits too (e.g. pasting several agents in at once).
 * A row is only provisioned once it has a plausible email in column B —
 * a row still being typed into (no "@" yet) is simply skipped, and will
 * get picked up on the next edit once the email is complete. Re-editing
 * an already-provisioned row is harmless: pa_ensureUserRecords_ skips
 * anything that already exists.
 *
 * ALSO: If the email column (B) was changed on a single cell edit,
 * automatically cascades the email change to Credentials, Sessions, and
 * Agents roster rows (if any) so all tables stay in sync without manual
 * intervention. For multi-cell range edits, runs reconciliation after
 * provisioning to catch any resulting mismatches.
 */
function pa_onAgentAccessEdit_(e) {
  try {
    const range = e.range;
    const sh = range.getSheet();
    const startRow = range.getRow();
    const numRows = range.getNumRows();
    const editedColumn = range.getColumn();
    const lastCol = Math.max(sh.getLastColumn(), AA_COL_.ALIASES + 1);

    // Single-cell edit in email column (B = column 2) — cascade the change
    if (numRows === 1 && editedColumn === 2 && e.oldValue !== undefined && e.value !== undefined) {
      const oldEmail = pa_normEmail_(e.oldValue);
      const newEmail = pa_normEmail_(e.value);
      if (oldEmail && newEmail && oldEmail !== newEmail) {
        pa_cascadeEmailChange_(oldEmail, newEmail, 'agentAccess');
      }
    }

    // Multi-row or multi-column edits — provision new rows and then
    // reconcile to catch any email mismatches that might have resulted
    // B Email, C Canonical Name, D Role, F Status, G Aliases are the single-cell edits handled above/below without a full reconcile
    const isMultiEdit = numRows > 1 || [2, 3, 4, 6, 7].indexOf(editedColumn) === -1;
    const anyRowProvisioned = false;

    for (let row = startRow; row < startRow + numRows; row++) {
      if (row < 2) continue; // header row
      const rowValues = sh.getRange(row, 1, 1, lastCol).getValues()[0];
      const email = pa_normEmail_(rowValues[1]);   // column B = Email
      const canonicalName = rowValues[AA_COL_.CANONICAL]; // column C = Canonical Name
      const role = rowValues[AA_COL_.ROLE];               // column D = Role
      if (!email || email.indexOf('@') === -1) continue;
      pa_ensureUserRecords_(email, canonicalName, role);
    }

    // After multi-edits, run reconciliation to catch any resulting mismatches
    if (isMultiEdit) {
      pa_reconcileAuthTables_();
    }
  } catch (err) {
    Logger.log('pa_onAgentAccessEdit_ error: ' + err.toString());
  }
}

/**
 * Cascades an email change across Credentials, Sessions, and Agents roster
 * (depending on source table). Called from onEdit when someone edits the
 * email cell directly. If oldEmail has a row in Credentials/Sessions/Agents,
 * updates that row's email to newEmail. If a row already exists with newEmail
 * in a table, skips that table (to avoid creating duplicates).
 * @param {string} oldEmail normalized email that's being changed
 * @param {string} newEmail normalized email it's being changed to
 * @param {string} source which table is being edited ('agentAccess', 'agents')
 */
function pa_cascadeEmailChange_(oldEmail, newEmail, source) {
  if (!oldEmail || !newEmail) return;

  // Credentials: update old email → new email (always, from either source)
  try {
    const credSh = pa_credentialsSheet_();
    const oldRow = pa_findRow_(credSh, 1, oldEmail); // column A = Email
    const newRow = pa_findRow_(credSh, 1, newEmail);
    if (oldRow !== -1 && newRow === -1) {
      credSh.getRange(oldRow, 1).setValue(newEmail);
      Logger.log('pa_cascadeEmailChange_ Credentials: ' + oldEmail + ' → ' + newEmail);
    }
  } catch (e) {
    Logger.log('pa_cascadeEmailChange_ Credentials failed: ' + e.toString());
  }

  // Sessions: update all rows with old email → new email (always, from either source)
  try {
    const sessSh = pa_sessionsSheet_();
    const sessRows = pa_sheetRows_(sessSh);
    const newEmailUsed = sessRows.some(r => pa_normEmail_(r[1]) === newEmail);
    if (!newEmailUsed) {
      for (let i = 0; i < sessRows.length; i++) {
        if (pa_normEmail_(sessRows[i][1]) === oldEmail) {
          sessSh.getRange(i + 2, 2).setValue(newEmail); // column B = Email
          Logger.log('pa_cascadeEmailChange_ Sessions row ' + (i + 2) + ': ' + oldEmail + ' → ' + newEmail);
        }
      }
    }
  } catch (e) {
    Logger.log('pa_cascadeEmailChange_ Sessions failed: ' + e.toString());
  }

  // Agent Access: update old email → new email (if source is agents)
  if (source === 'agents') {
    try {
      const accessSh = pa_agentAccessSheet_();
      const oldRow = pa_findRow_(accessSh, 2, oldEmail); // column B = Email
      const newRow = pa_findRow_(accessSh, 2, newEmail);
      if (oldRow !== -1 && newRow === -1) {
        accessSh.getRange(oldRow, 2).setValue(newEmail);
        Logger.log('pa_cascadeEmailChange_ Agent Access: ' + oldEmail + ' → ' + newEmail);
      }
    } catch (e) {
      Logger.log('pa_cascadeEmailChange_ Agent Access failed: ' + e.toString());
    }
  }

  // Agents roster: update old email → new email (if source is agentAccess)
  if (source === 'agentAccess') {
    try {
      const agents = getAgents(); // Code.gs
      const oldAgent = agents.find(a => pa_normEmail_(a['Email']) === oldEmail);
      const newAgent = agents.find(a => pa_normEmail_(a['Email']) === newEmail);
      if (oldAgent && !newAgent) {
        const sh = SpreadsheetApp.openById(TARGET_SHEET_ID).getSheetByName(SHEET_AGENTS);
        if (sh) {
          const data = sh.getDataRange().getValues();
          for (let i = 1; i < data.length; i++) {
            if (pa_normEmail_(data[i][2]) === oldEmail) { // column C = Email
              sh.getRange(i + 1, 3).setValue(newEmail);
              Logger.log('pa_cascadeEmailChange_ Agents roster: ' + oldEmail + ' → ' + newEmail);
              break;
            }
          }
        }
      }
    } catch (e) {
      Logger.log('pa_cascadeEmailChange_ Agents roster failed: ' + e.toString());
    }
  }
}

// ── Session management ───────────────────────────────────────
function pa_createSession_(email) {
  const sh = pa_sessionsSheet_();
  if (!sh) throw new Error('Sessions sheet not found — check the "Sessions" tab exists and is named exactly "Sessions".');
  const sessionId = Utilities.getUuid();
  const now = new Date();
  const expires = new Date(now.getTime() + SESSION_TTL_HOURS * 60 * 60 * 1000);
  pa_appendRowAfterData_(sh, 1, [sessionId, pa_normEmail_(email), now, expires]); // Sessions: sessionId col A
  return sessionId;
}

/** Private validator used by PortalData.gs's pa_authorize_(). Returns {valid, email} or {valid:false}. */
function pa_validateSession_(sessionId) {
  if (!sessionId) return { valid: false };
  const sh = pa_sessionsSheet_();
  const rows = pa_sheetRows_(sh);
  for (let i = 0; i < rows.length; i++) {
    if (rows[i][0] === sessionId) {
      const expires = rows[i][3];
      if (expires && new Date(expires) < new Date()) {
        sh.deleteRow(i + 2); // expired — clean it up
        return { valid: false };
      }
      return { valid: true, email: rows[i][1] };
    }
  }
  return { valid: false };
}

function pa_deleteSession_(sessionId) {
  const sh = pa_sessionsSheet_();
  const rowNum = pa_findRow_(sh, 1, sessionId);
  if (rowNum !== -1) sh.deleteRow(rowNum);
}

// ══════════════════════════════════════════════════════════
// ADMIN — Portal user access management (Agent Access sheet)
// Every function below requires a valid session belonging to a user
// whose Agent Access role is "Admin". This is the actual security
// boundary for the Admin panel — the client-side "Admin" nav tab is
// only a convenience, never trust it alone.
// ══════════════════════════════════════════════════════════

/** Requires an active session AND an Admin role. Returns {ok, email, aliases, role} or {ok:false, error}. */
function pa_isAdmin_(sessionId) {
  try {
    const auth = pa_authorize_(sessionId); // defined in PortalData.gs
    if (!auth || !auth.ok) return auth || { ok: false, error: 'Session expired. Please log in again.' };
    if (String(auth.role || '').trim().toUpperCase() !== 'ADMIN') {
      return { ok: false, error: 'Admin access required.' };
    }
    return auth;
  } catch (e) {
    Logger.log('pa_isAdmin_ error: ' + e.toString());
    return { ok: false, error: 'Authorization check failed: ' + e.toString() };
  }
}

/** Internal (no auth check) — used by pa_adminListUsers and the admin overview. */
function pa_adminListUsers_() {
  const rows = pa_sheetRows_(pa_agentAccessSheet_());
  return rows
    .filter(r => String(r[AA_COL_.EMAIL] || '').trim() !== '') // skip blank rows (no email = not a real user)
    .map(r => {
      const names = pa_buildAccessNames_(r[AA_COL_.CANONICAL], r[AA_COL_.ALIASES]);
      const activeCell = r[AA_COL_.ACTIVE];
      return {
        userId: r[AA_COL_.USER_ID] || '',
        email: r[AA_COL_.EMAIL] || '',
        canonicalName: names.canonicalName,
        aliasesCsv: names.extraAliases.join('; '), // OTHER spellings only — canonicalName is separate
        role: r[AA_COL_.ROLE] || '',
        active: activeCell === true || String(activeCell).toUpperCase() === 'TRUE'
      };
    });
}

/** Admin: returns every portal user whose last login (Credentials column D)
 *  falls on today's date (server timezone) — powers the "Logged In Today"
 *  panel on the Admin > User Overview card. */
function pa_adminGetTodayLogins(sessionId) {
  const auth = pa_isAdmin_(sessionId);
  if (!auth.ok) return auth;

  const tz = Session.getScriptTimeZone();
  const todayStr = Utilities.formatDate(new Date(), tz, 'yyyy-MM-dd');

  const credRows = pa_sheetRows_(pa_credentialsSheet_());
  const accessByEmail = {};
  pa_adminListUsers_().forEach(u => { accessByEmail[pa_normEmail_(u.email)] = u; });

  const logins = [];
  credRows.forEach(r => {
    const email = pa_normEmail_(r[0]);
    const lastLogin = r[3]; // column D
    if (!email || !lastLogin) return;
    const d = new Date(lastLogin);
    if (isNaN(d.getTime())) return;
    if (Utilities.formatDate(d, tz, 'yyyy-MM-dd') !== todayStr) return;

    const access = accessByEmail[email];
    logins.push({
      email: email,
      lastLogin: Utilities.formatDate(d, tz, 'MM/dd/yyyy hh:mm a'),
      lastLoginRaw: d.getTime(),
      displayName: access ? (access.canonicalName || pa_parseAliasesCsv_(access.aliasesCsv)[0] || '') : '',
      role: access ? access.role : '',
      active: access ? access.active : true
    });
  });

  logins.sort((a, b) => b.lastLoginRaw - a.lastLoginRaw);
  return { ok: true, logins: logins, count: logins.length };
}

/** Admin: lists every row in the Agent Access sheet. Self-heals first
 *  (pa_reconcileAuthTables_) so rows deleted by hand directly in the
 *  Sheets UI — which bypass every cascade-delete above — are already
 *  cleaned up across Credentials/Sessions/Agents roster before the list
 *  is built, instead of showing stale/orphaned entries. */
function pa_adminListUsers(sessionId) {
  const auth = pa_isAdmin_(sessionId);
  if (!auth.ok) return auth;
  pa_reconcileAuthTables_();
  return { ok: true, users: pa_adminListUsers_() };
}

/** Admin: adds a new authorized portal user. payload: {email, canonicalName, aliasesCsv, role, active}.
 *  Inserted directly below the last existing Agent Access row (not appended
 *  to the sheet's absolute bottom, which can drift down if there are extra
 *  blank/formatted rows below the data). Also provisions a Credentials row,
 *  and — if role is "Agent" — an Agents roster row, via pa_ensureUserRecords_,
 *  so adding someone here behaves identically to pa_addAgentAccess_(). */
function pa_adminAddUser(sessionId, payload) {
  const auth = pa_isAdmin_(sessionId);
  if (!auth.ok) return auth;

  payload = payload || {};
  const email = pa_normEmail_(payload.email);
  if (!email) return { ok: false, error: 'Email is required.' };
  if (pa_getAccessRecord_(email)) return { ok: false, error: 'A user with this email already exists.' };

  const canonicalName = pa_cleanCanonicalName_(payload.canonicalName);
  if (canonicalName === null) {
    return { ok: false, error: 'Canonical Name must be a single name. Put other spellings in Aliases (separated by semicolons).' };
  }
  const aliasesCsv = pa_buildAccessNames_(canonicalName, payload.aliasesCsv).extraAliases.join('; ');

  const role = payload.role || 'Agent';
  const active = payload.active !== false;
  const userId = pa_generateUserId_();
  pa_insertAgentAccessRowBelowLast_(userId, email, canonicalName, role, active, aliasesCsv);
  pa_ensureUserRecords_(email, canonicalName, role);

  let warning = null;
  if (active) {
    // Newly-created access, first time — send the invite immediately rather
    // than leaving it to the separate manual "Send password setup link"
    // button (still available on the row for a resend later, e.g. if the
    // first email bounces or the link expires unused).
    try {
      pa_requestPasswordAction(email, 'setup');
    } catch (e) {
      Logger.log('pa_adminAddUser: pa_requestPasswordAction failed for ' + email + ' — ' + e.toString());
      warning = 'User added, but the setup-password email could not be sent automatically. Use the paper-plane icon to resend.';
    }
  }
  return { ok: true, userId: userId, warning: warning };
}

/** Inserts a new Agent Access row directly below the last row that actually
 *  has an email in it (see pa_lastRowWithData_ / pa_appendRowAfterData_
 *  above) — NOT sh.getLastRow(), which on this sheet is inflated by a wide
 *  checkbox-formatted range on the Active column (hundreds of rows with a
 *  literal FALSE and nothing else). Using getLastRow() here was the actual
 *  bug behind "adding a user doesn't add a user": every new row landed
 *  ~400 rows below the last real user, invisible unless you scrolled all
 *  the way down. Shared by pa_adminAddUser() (admin panel) —
 *  pa_addAgentAccess_() (Auth.gs, the console/admin helper) uses this too,
 *  so both add paths land a new user in the same place. */
function pa_insertAgentAccessRowBelowLast_(userId, email, canonicalName, role, active, aliasesCsv) {
  const sh = pa_agentAccessSheet_(); // also guarantees the Aliases column (G) exists
  // Agent Access: A User ID, B Email, C Canonical Name, D Role, E Active, F Status (not ours), G Aliases
  // Write A:E, then G on its own — column F (Status) is deliberately skipped so
  // it is never overwritten (it may hold a formula or hand-entered values).
  const row = pa_appendRowAfterData_(sh, 2, [userId, email, canonicalName || '', role, active]); // key col = Email (B)
  if (aliasesCsv) sh.getRange(row, AA_COL_.ALIASES + 1).setValue(aliasesCsv);
}

/** Admin: updates an existing portal user, matched by original email. */
function pa_adminUpdateUser(sessionId, originalEmail, payload) {
  const auth = pa_isAdmin_(sessionId);
  if (!auth.ok) return auth;

  payload = payload || {};
  const sh = pa_agentAccessSheet_();
  const rowNum = pa_findRow_(sh, 2, originalEmail);
  if (rowNum === -1) return { ok: false, error: 'User not found.' };

  // Validate before writing anything.
  let canonicalName = null; // null = not being changed
  if (payload.canonicalName !== undefined) {
    canonicalName = pa_cleanCanonicalName_(payload.canonicalName);
    if (canonicalName === null) {
      return { ok: false, error: 'Canonical Name must be a single name. Put other spellings in Aliases (separated by semicolons).' };
    }
  }

  const newEmail = pa_normEmail_(payload.email);
  if (newEmail && newEmail !== pa_normEmail_(originalEmail)) {
    if (pa_getAccessRecord_(newEmail)) return { ok: false, error: 'Another user already uses that email.' };
    sh.getRange(rowNum, AA_COL_.EMAIL + 1).setValue(newEmail);
  }
  if (canonicalName !== null) sh.getRange(rowNum, AA_COL_.CANONICAL + 1).setValue(canonicalName);
  if (payload.aliasesCsv !== undefined) {
    // Drop any alias that just repeats the canonical name, and normalise separators to "; ".
    const effectiveCanonical = canonicalName !== null
      ? canonicalName
      : pa_buildAccessNames_(sh.getRange(rowNum, AA_COL_.CANONICAL + 1).getValue(), '').canonicalName;
    sh.getRange(rowNum, AA_COL_.ALIASES + 1)
      .setValue(pa_buildAccessNames_(effectiveCanonical, payload.aliasesCsv).extraAliases.join('; '));
  }
  if (payload.role !== undefined) sh.getRange(rowNum, AA_COL_.ROLE + 1).setValue(payload.role);
  if (payload.active !== undefined) sh.getRange(rowNum, AA_COL_.ACTIVE + 1).setValue(!!payload.active);

  return { ok: true };
}

/** Admin: removes a portal user's access and cleans up their credentials/sessions.
 *  If the removed user's role was "Agent", also removes their matching row
 *  from the Agents roster (Code.gs) — so deleting access here shows up on
 *  the Admin panel's Agents tab too, instead of leaving a roster row for
 *  someone who can no longer log in. See deleteAgent() (Code.gs) for the
 *  same cascade in the opposite direction. */
function pa_adminDeleteUser(sessionId, email) {
  const auth = pa_isAdmin_(sessionId);
  if (!auth.ok) return auth;

  const target = pa_normEmail_(email);
  if (target === pa_normEmail_(auth.email)) {
    return { ok: false, error: "You can't remove your own account while logged in." };
  }

  // Guard: never allow removing the last active Admin.
  const users = pa_adminListUsers_();
  const activeAdmins = users.filter(u => u.active && String(u.role).toUpperCase() === 'ADMIN');
  const targetUser = users.find(u => pa_normEmail_(u.email) === target);
  if (!targetUser) return { ok: false, error: 'User not found.' };
  if (targetUser.active && String(targetUser.role).toUpperCase() === 'ADMIN' && activeAdmins.length <= 1) {
    return { ok: false, error: 'Cannot remove the last active Admin.' };
  }

  const removed = pa_removeAgentAccessRow_(target);
  if (!removed) return { ok: false, error: 'User not found.' };

  if (String(targetUser.role || '').trim().toLowerCase() === 'agent') {
    try {
      deleteAgentByEmail_(target); // Code.gs — keep the Agents roster in sync
    } catch (e) {
      Logger.log('pa_adminDeleteUser: deleteAgentByEmail_ failed for ' + target + ' — ' + e.toString());
    }
  }

  return { ok: true };
}

/** Removes the Agent Access row for `email` plus its Credentials and
 *  Session rows. This is the shared "hard delete" of a login identity —
 *  used by pa_adminDeleteUser() (explicit admin action) and by
 *  pa_reconcileAuthTables_() / pa_cascadeDeleteAgentAccessIfRoleAgent_()
 *  (system cleanup after a related row disappeared elsewhere). Returns
 *  false (no-op) if there's no matching Agent Access row. Does NOT apply
 *  the self-delete / last-admin guards — callers that need those
 *  (pa_adminDeleteUser) check them before calling this. */
function pa_removeAgentAccessRow_(email) {
  const target = pa_normEmail_(email);
  if (!target) return false;

  const sh = pa_agentAccessSheet_();
  const rowNum = pa_findRow_(sh, 2, target);
  if (rowNum === -1) return false;
  sh.deleteRow(rowNum);

  // Best-effort cleanup — a missing credentials/session row is not an error.
  try {
    const credRow = pa_findCredentialRow_(target);
    if (credRow !== -1) pa_credentialsSheet_().deleteRow(credRow);
  } catch (e) {
    Logger.log('pa_removeAgentAccessRow_ credentials cleanup failed for ' + target + ' — ' + e.toString());
  }
  try {
    const sessSh = pa_sessionsSheet_();
    const sessRows = pa_sheetRows_(sessSh);
    for (let i = sessRows.length - 1; i >= 0; i--) {
      if (pa_normEmail_(sessRows[i][1]) === target) sessSh.deleteRow(i + 2);
    }
  } catch (e) {
    Logger.log('pa_removeAgentAccessRow_ sessions cleanup failed for ' + target + ' — ' + e.toString());
  }

  return true;
}

/** Called from deleteAgent() (Code.gs) whenever an Agents-roster row is
 *  removed — revokes portal access to match, but ONLY if that access was
 *  role "Agent". Never touches a Supervisor/Manager/Admin account just
 *  because a same-email Agents roster row happened to be deleted — those
 *  roles aren't expected to have a roster row in the first place. */
function pa_cascadeDeleteAgentAccessIfRoleAgent_(email) {
  const target = pa_normEmail_(email);
  if (!target) return;
  const access = pa_getAccessRecord_(target);
  if (access && String(access.role || '').trim().toLowerCase() === 'agent') {
    pa_removeAgentAccessRow_(target);
  }
}

/**
 * Self-healing sync across Agent Access, Credentials, Sessions, and the
 * Agents roster (Code.gs) — run before every Admin panel read (see
 * pa_adminListUsers / pa_adminGetAgents / pa_adminOverview) so the panel
 * always reflects the sheets' true current state, however a row went
 * missing. This exists specifically for deletions made by typing/
 * right-click-deleting a row directly in the Sheets UI: Apps Script's
 * onEdit trigger (pa_onAgentAccessEdit_) only fires on cell value changes,
 * NOT on row deletion, so a manual delete never reaches any of the
 * cascade-delete functions above and would otherwise leave orphaned rows
 * behind indefinitely.
 *
 * Rules, all keyed by normalized email:
 *   1. An Agent Access row with no Credentials row gets a fresh placeholder
 *      Credentials row recreated (mirrors what pa_ensureUserRecords_ does
 *      at add-time) — Credentials is a derived login artifact, not
 *      business data, so it's always safe to recreate.
 *   2. Credentials / Sessions rows with no matching Agent Access row are
 *      orphaned login artifacts for someone who no longer has access —
 *      removed outright, for every role.
 *   3. Agents roster rows are kept in sync with Agent Access ONLY for
 *      role "Agent" specifically (a Supervisor/Manager/Admin is expected
 *      to have no roster row):
 *        - Roster row present, but no matching role-Agent Access row
 *          exists at all -> the roster row is removed (deleteAgent()).
 *        - Role-Agent Access row present, but no matching roster row
 *          exists -> the Access row (+ Credentials/Sessions) is removed.
 *      Either side's deletion revokes the other — this never fires just
 *      because a role changed away from "Agent" while the row still exists.
 *
 * Returns a summary of what was cleaned up, for logging.
 */
