function pa_reconcileAuthTables_() {
  const summary = {
    credentialsRecreated: [], credentialsWouldRemove: [], sessionsWouldRemove: [],
    agentsRosterWouldRemove: [], agentsRosterRecreated: []
  };

  // Prevent overlapping runs (trigger + admin panel at the same time)
  const lock = LockService.getScriptLock();
  if (!lock.tryLock(10000)) {
    Logger.log('pa_reconcileAuthTables_: another run is in progress — skipped.');
    return summary;
  }

  try {
    const accessRows = pa_adminListUsers_();
    const accessByEmail = {};
    accessRows.forEach(u => { accessByEmail[pa_normEmail_(u.email)] = u; });

    // 1. Agent Access rows missing a Credentials row -> recreate (add only)
    try {
      accessRows.forEach(u => {
        const email = pa_normEmail_(u.email);
        if (email && pa_findCredentialRow_(email) === -1) {
          pa_appendRowAfterData_(pa_credentialsSheet_(), 1, [email, '', false, '', new Date()]);
          summary.credentialsRecreated.push(email);
        }
      });
    } catch (e) {
      Logger.log('pa_reconcileAuthTables_: Credentials recreate failed — ' + e.toString());
    }

    // 2a. Credentials with no Agent Access row -> LOG ONLY
    try {
      pa_sheetRows_(pa_credentialsSheet_()).forEach(r => {
        const email = pa_normEmail_(r[0]);
        if (email && !accessByEmail[email]) summary.credentialsWouldRemove.push(email);
      });
    } catch (e) {
      Logger.log('pa_reconcileAuthTables_: Credentials check failed — ' + e.toString());
    }

    // 2b. Sessions with no Agent Access row -> LOG ONLY
    try {
      pa_sheetRows_(pa_sessionsSheet_()).forEach(r => {
        const email = pa_normEmail_(r[1]);
        if (email && !accessByEmail[email]) summary.sessionsWouldRemove.push(email);
      });
    } catch (e) {
      Logger.log('pa_reconcileAuthTables_: Sessions check failed — ' + e.toString());
    }

    // 3. Agents roster sync
    try {
      const agents = getAgents();
      const rosterByEmail = {};
      agents.forEach(a => { const e = pa_normEmail_(a['Email']); if (e) rosterByEmail[e] = a; });

      // 3a. Roster row with no Agent Access row -> LOG ONLY
      agents.forEach(a => {
        const email = pa_normEmail_(a['Email']);
        if (email && !accessByEmail[email]) summary.agentsRosterWouldRemove.push(email);
      });

      // 3b. Role-Agent access row with no roster row -> create roster row (add only)
      accessRows.forEach(u => {
        const email = pa_normEmail_(u.email);
        if (String(u.role || '').trim().toLowerCase() !== 'agent') return;
        if (rosterByEmail[email]) return;
        const r = pa_ensureUserRecords_(email, u.canonicalName, u.role);
        if (r.agentsRoster === 'added') summary.agentsRosterRecreated.push(email);
      });
    } catch (e) {
      Logger.log('pa_reconcileAuthTables_: Agents roster sync failed — ' + e.toString());
    }

    const anything = Object.keys(summary).some(k => summary[k].length);
    if (anything) Logger.log('pa_reconcileAuthTables_ summary: ' + JSON.stringify(summary));
    return summary;
  } finally {
    lock.releaseLock();
  }
}

// ── Password hashing (salted SHA-256 — Apps Script has no bcrypt) ──
function pa_makeSalt_() {
  return Utilities.getUuid();
}

function pa_hash_(password, salt) {
  const bytes = Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256, salt + password);
  return bytes.map(b => ('0' + (b & 0xFF).toString(16)).slice(-2)).join('');
}

function pa_findCredentialRow_(email) {
  return pa_findRow_(pa_credentialsSheet_(), 1, email);
}

function pa_setPasswordHash_(email, plainPassword) {
  email = pa_normEmail_(email);
  const sh = pa_credentialsSheet_();
  const salt = pa_makeSalt_();
  const hash = salt + '$' + pa_hash_(plainPassword, salt);
  const rowNum = pa_findCredentialRow_(email);
  if (rowNum === -1) {
    pa_appendRowAfterData_(sh, 1, [email, hash, true, '', new Date()]); // Credentials: Email col A
  } else {
    sh.getRange(rowNum, 2).setValue(hash);
    sh.getRange(rowNum, 3).setValue(true);
  }
}

function pa_verifyPassword_(email, plainPassword) {
  const rowNum = pa_findCredentialRow_(pa_normEmail_(email));
  if (rowNum === -1) return false;
  const stored = String(pa_credentialsSheet_().getRange(rowNum, 2).getValue() || '');
  const parts = stored.split('$');
  if (parts.length !== 2) return false;
  const [salt, hash] = parts;
  return pa_hash_(plainPassword, salt) === hash;
}

function pa_updateLastLogin_(email) {
  email = pa_normEmail_(email);
  const sh = pa_credentialsSheet_();
  const rowNum = pa_findCredentialRow_(email);
  const now = new Date();
  if (rowNum === -1) {
    pa_appendRowAfterData_(sh, 1, [email, '', false, now, now]); // Credentials: Email col A
  } else {
    sh.getRange(rowNum, 4).setValue(now);
  }
}

// ── Login / password tokens ─────────────────────────────────
function pa_createToken_(email, type) {
  email = pa_normEmail_(email);
  // Only the newest link should ever work — kill off anything still outstanding first.
  pa_expireOutstandingTokens_(email, type);
  const sh = pa_loginTokensSheet_();
  const token = Utilities.getUuid() + Utilities.getUuid();
  const now = new Date();
  const expires = new Date(now.getTime() + TOKEN_TTL_MINUTES * 60 * 1000);
  pa_appendRowAfterData_(sh, 1, [token, email, type, now, expires, false]); // Login Tokens: Token col A
  return token;
}

/** Expires (without deleting) every still-outstanding, unused token of a given type for an
 *  email. Called right before a new token of that type is minted so old, unused verification
 *  links stop working the moment a fresh one is generated. */
function pa_expireOutstandingTokens_(email, type) {
  const sh = pa_loginTokensSheet_();
  const rows = pa_sheetRows_(sh);
  const target = pa_normEmail_(email);
  const now = new Date();
  for (let i = 0; i < rows.length; i++) {
    const used = rows[i][5] === true || String(rows[i][5]).toUpperCase() === 'TRUE';
    if (!used && rows[i][2] === type && pa_normEmail_(rows[i][1]) === target) {
      sh.getRange(i + 2, 5).setValue(now); // column E = expiresAt -> now, i.e. expired
    }
  }
}

/** Seconds since the most recently created token of a given type for this email, or null if none exist. */
function pa_secondsSinceLastToken_(email, type) {
  const rows = pa_sheetRows_(pa_loginTokensSheet_());
  const target = pa_normEmail_(email);
  let latest = null;
  for (let i = 0; i < rows.length; i++) {
    if (rows[i][2] === type && pa_normEmail_(rows[i][1]) === target) {
      const created = rows[i][3];
      if (created && (!latest || new Date(created) > latest)) latest = new Date(created);
    }
  }
  if (!latest) return null;
  return (new Date().getTime() - latest.getTime()) / 1000;
}

/** True if a token of this type was generated for this email too recently — used to throttle
 *  rapid-fire link requests (e.g. someone mashing "resend link"). */
function pa_isTokenRequestRateLimited_(email, type) {
  const seconds = pa_secondsSinceLastToken_(email, type);
  return seconds !== null && seconds < TOKEN_REQUEST_COOLDOWN_SECONDS;
}

/** Non-consuming lookup — used to preview a token's validity before showing the set-password form. */
function pa_findToken_(token, type) {
  const rows = pa_sheetRows_(pa_loginTokensSheet_());
  for (let i = 0; i < rows.length; i++) {
    if (rows[i][0] === token && rows[i][2] === type) {
      return { used: rows[i][5] === true || String(rows[i][5]).toUpperCase() === 'TRUE', expiresAt: rows[i][4] };
    }
  }
  return null;
}

/** Consuming lookup — marks the token used and returns the associated email. */
function pa_consumeToken_(token, type) {
  const sh = pa_loginTokensSheet_();
  const rows = pa_sheetRows_(sh);
  for (let i = 0; i < rows.length; i++) {
    if (rows[i][0] === token && rows[i][2] === type) {
      const used = rows[i][5] === true || String(rows[i][5]).toUpperCase() === 'TRUE';
      if (used) return { valid: false, error: 'This link has already been used.' };
      if (rows[i][4] && new Date(rows[i][4]) < new Date()) {
        return { valid: false, error: 'This link has expired.' };
      }
      sh.getRange(i + 2, 6).setValue(true);
      return { valid: true, email: rows[i][1] };
    }
  }
  return { valid: false, error: 'This link is invalid.' };
}

// ── Email delivery ───────────────────────────────────────────
/** Decodes PA_EMAIL_LOGO_DATA_URI into a Blob so it can be sent as a real
 *  CID-embedded inline image (MailApp's `inlineImages` option) instead of a
 *  `data:` URI in the <img> src. Many mail clients — Gmail included —
 *  strip or refuse to render `data:` URI images for security reasons, which
 *  shows up as a broken-image icon even though the HTML itself is fine.
 *  CID embedding is the standard, widely-supported way Apps Script emails
 *  ship inline images, so this is what every branded template should use. */
function pa_logoBlob_() {
  const base64 = PA_EMAIL_LOGO_DATA_URI.replace(/^data:image\/png;base64,/, '');
  return Utilities.newBlob(Utilities.base64Decode(base64), 'image/png', 'inner-sparc-logo.png');
}

/** The inlineImages map to pass to pa_sendMail_ for any HTML body that
 *  references the logo via `src="cid:innerSparcLogo"` (see
 *  pa_buildBrandedEmailHtml_). Keyed to match that cid exactly. */
function pa_logoInlineImages_() {
  return { innerSparcLogo: pa_logoBlob_() };
}

function pa_buildActionUrl_(action, token) {
  const base = ScriptApp.getService().getUrl();
  return base + '?action=' + encodeURIComponent(action) + '&token=' + encodeURIComponent(token);
}

/** Sends `body` as the plain-text fallback and, when `htmlBody` is given, an
 *  HTML alternative too. IMPORTANT: every login/reset/setup link in this
 *  file MUST go through the htmlBody path (a real `<a href="...">`), not
 *  plain text. The webapp URL + "?action=verify&token=" + our 72-character
 *  token (two UUIDs concatenated in pa_createToken_) easily runs past the
 *  ~76-78 char/line soft-wrap that plain-text mail transport applies —
 *  and unlike quoted-printable HTML (where that wrap is a "=\r\n" soft
 *  break that decoding removes, restoring one continuous href), a wrapped
 *  URL sitting in a plain-text body often does NOT get rejoined by the
 *  reading client. The user then clicks a truncated/broken link, the token
 *  in it no longer matches any Login Tokens row, and pa_verifyLoginToken /
 *  pa_checkPasswordToken report "This link is invalid" — the link was
 *  genuinely sent, it just silently broke in transit. Wrapping the same
 *  URL in an anchor tag's href attribute isn't subject to that visual
 *  line-wrap problem, so it always arrives intact.
 *  `inlineImages`, when given, is passed straight through to MailApp as the
 *  cid → Blob map (see pa_logoInlineImages_) for any `cid:...` references in
 *  `htmlBody`. */
function pa_sendMail_(email, subject, body, htmlBody, inlineImages) {
  if (htmlBody) {
    try {
      // Sender display name is force-set here (not left to caller options)
      // so every login/reset/setup email — regardless of call site — shows
      // the same "From" name, even if a future caller passes its own
      // `name` in a spread/extend of this options object.
      const options = { htmlBody: htmlBody, name: 'Innersparc Realty Corporation' };
      if (inlineImages) options.inlineImages = inlineImages;
      MailApp.sendEmail(email, subject, body, options);
      return true;
    } catch (e) {
      // Falling back below instead of giving up outright: this combined
      // call can fail for reasons that have nothing to do with the email
      // itself — e.g. the script's OAuth authorization was granted before
      // the htmlBody option was added to this code and hasn't been
      // re-approved yet (Apps Script silently rejects newly-added advanced
      // calls until someone reruns any function from the editor and
      // accepts the permission prompt), or the daily MailApp quota ran
      // out mid-testing. Without this fallback, a hiccup on the HTML path
      // meant NO email went out at all — a plain-text-only send is a much
      // better failure mode than total silence.
      Logger.log('pa_sendMail_: htmlBody send failed for ' + email + ' — ' + e.toString() +
        '. Remaining daily quota: ' + (function(){ try { return MailApp.getRemainingDailyQuota(); } catch(_) { return 'unknown'; } })() +
        '. Retrying as plain text only.');
    }
  }
  try {
    MailApp.sendEmail(email, subject, body, { name: 'Innersparc Realty Corporation' });
    return true;
  } catch (e) {
    Logger.log('pa_sendMail_ failed for ' + email + ': ' + e.toString() +
      '. Remaining daily quota: ' + (function(){ try { return MailApp.getRemainingDailyQuota(); } catch(_) { return 'unknown'; } })());
    return false;
  }
}


/** Escapes a string for safe interpolation into an HTML attribute/body. */
function pa_escapeHtml_(s) {
  return String(s || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

/** Builds the shared HTML body for every login/setup/reset email: a real
 *  <a href> so the full URL (base + action + our long token) always
 *  survives mail-client line-wrapping intact — see pa_sendMail_ above for
 *  why that matters. `introText`/`expiryText` are plain sentences; the
 *  link itself is the only markup. */
function pa_buildLinkEmailHtml_(introText, url, expiryText) {
  const safeUrl = pa_escapeHtml_(url);
  return '<p>' + pa_escapeHtml_(introText) + '</p>' +
    '<p><a href="' + safeUrl + '">' + safeUrl + '</a></p>' +
    '<p>' + pa_escapeHtml_(expiryText) + '</p>' +
    '<p>If you did not request this, you can ignore this email.</p>';
}

// ══════════════════════════════════════════════════════════
// BRANDED EMAIL TEMPLATE — password-change / magic-link emails
